INSERT INTO film_comments (
    id,
    name,
    slug,
    views,
    type,
    short_description,
    image_landscape,
    image_portrait,
    description,
    is_hot,
    display_order,
    created_at
) VALUES (
             '019c10ca-8e7d-4bd3-8845-566b56dafe9a',
             '[Review] Tử Chiến Trên Không: Phim Việt Xuất Sắc Top Đầu 2025!',
             'tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025',
             1245,
             'review',
             '<p><span style="font-size:14px;"><span style="font-family:Arial,Helvetica,sans-serif;"><span style="line-height:115%">Với một <b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b> xuất sắc, điện ảnh Việt Nam c&oacute; thể mơ đến việc đa dạng thể loại hơn tr&ecirc;n m&agrave;n ảnh rộng.</span></span></span></p>\n',
             'https://cdn.galaxycine.vn/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-1_1758597702205.jpg',
             'https://cdn.galaxycine.vn/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-3_1758597696239.jpg',
             '<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Với một <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> xuất sắc, điện ảnh Việt Nam c&oacute; thể mơ đến việc đa dạng thể loại hơn tr&ecirc;n m&agrave;n ảnh rộng.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px;\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">L&agrave; nền điện ảnh sở hữu bề d&agrave;y lịch sử đ&aacute;ng nể, từng sản xuất ra những t&aacute;c phẩm kinh điển như <i>Bao Giờ Cho Đến Th&aacute;ng Mười</i>, <i>Đ&ecirc;m Hội Long Tr&igrave;</i>, <i>C&aacute;nh Đồng Hoang</i>&hellip; v&agrave;i năm gần đ&acirc;y, điện ảnh Việt Nam trở n&ecirc;n k&eacute;m đa dạng hơn c&aacute;c người anh em c&ugrave;ng khu vực ch&acirc;u &Aacute;. Đa số <a href=\"https://www.galaxycine.vn/phim-dang-chieu/\"><i>phim chiếu rạp</i></a> được c&ocirc;ng ch&uacute;ng ủng hộ nhiệt t&igrave;nh thường xoay quanh đề t&agrave;i m&acirc;u thuẫn gia đ&igrave;nh &ndash; thế hệ. Tuy nhi&ecirc;n, năm nay, phim Việt đ&atilde; bứt ph&aacute; ngoạn mục bằng <a href=\"https://www.galaxycine.vn/phim/tham-tu-kien-ky-an-khong-dau/\"><i>Th&aacute;m Tử Ki&ecirc;n: Kỳ &Aacute;n Kh&ocirc;ng Đầu</i></a> trinh th&aacute;m ph&aacute; &aacute;n, <a href=\"https://www.galaxycine.vn/dat-ve/mua-do/\"><i>Mưa Đỏ</i></a> lấy đề t&agrave;i chiến tranh v&agrave; giờ l&agrave; <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> &ndash; bộ phim về kh&ocirc;ng tặc đầu ti&ecirc;n của Việt Nam. </span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Do Điện ảnh C&ocirc;ng an nh&acirc;n d&acirc;n sản xuất dựa tr&ecirc;n hai vụ cướp m&aacute;y bay năm 1977 v&agrave; 1978 từng g&acirc;y chấn động dư luận, <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> vừa lấy cảm hứng vừa th&ecirc;m thắt hợp l&yacute; để tạo n&ecirc;n <a href=\"https://www.galaxycine.vn/phim-dang-chieu/\"><i>phim chiếu rạp</i></a> v&ocirc; c&ugrave;ng hấp dẫn. </span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Nh&acirc;n tố quan trọng h&agrave;ng đầu trong th&agrave;nh c&ocirc;ng về chất lượng của <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> ch&iacute;nh l&agrave; đạo diễn H&agrave;m Trần. Quyết t&acirc;m đầu tư xứng đ&aacute;ng cho dự &aacute;n đẳng cấp, đo&agrave;n phim phục dựng theo tỉ lệ 1:1 chiếc m&aacute;y bay sử dụng v&agrave;o giai đoạn đ&oacute;. Ch&iacute;nh v&igrave; vậy, bối cảnh phim diễn ra giữa kh&ocirc;ng gian m&aacute;y bay chật hẹp l&agrave; thử th&aacute;ch rất lớn cho ekip. Thế nhưng, H&agrave;m Trần đ&atilde; giải được b&agrave;i to&aacute;n kh&oacute; n&agrave;y nhờ c&aacute;ch đặt m&aacute;y quay đa dạng v&agrave; đổi g&oacute;c quay li&ecirc;n tục. Xem <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> chẳng hề l&agrave;m kh&aacute;n giả cảm thấy bị t&ugrave; t&úng hay chật chội.</span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Chuyển thể 52 ph&uacute;t căng thẳng trong vụ cướp m&aacute;y bay năm 1978 th&agrave;nh phim d&agrave;i 118 ph&uacute;t chẳng dễ ch&uacute;t n&agrave;o. Tuy nhi&ecirc;n, d&agrave;n bi&ecirc;n kịch phim đ&atilde; ho&agrave;n th&agrave;nh nhiệm vụ xuất sắc. Kịch bản chặt chẽ, mạch phim nhanh gọn. C&aacute;c c&acirc;u thoại c&agrave;i cắm đ&uacute;ng chất &ldquo;show, don&rsquo;t tell&rdquo;. Phim đưa người xem đi từ bất ngờ n&agrave;y đến bất ngờ kh&aacute;c. Tưởng b&igrave;nh y&ecirc;n th&igrave; biến cố mới lại xảy ra. Hấp dẫn, l&ocirc;i cuốn từng ph&uacute;t từng gi&acirc;y. Ngo&agrave;i ra, phim sở hữu nhiều lời thoại đậm t&iacute;nh gi&aacute;o dục nhưng chẳng hề s&aacute;o rỗng: &ldquo;Anh kh&ocirc;ng c&ograve;n hi vọng với đất nước n&agrave;y nhưng kh&ocirc;ng c&oacute; nghĩa l&agrave; đất nước n&agrave;y kh&ocirc;ng c&ograve;n tương lai.&rdquo; </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\"><img alt=\"\" height=\"315\" src=\"/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-7_1758600109520.jpg\" width=\"600\" /></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Sau giai đoạn ho&agrave;ng kim, v&agrave;i năm gần đ&acirc;y, t&aacute;c phẩm Th&aacute;i H&ograve;a tham gia chẳng phải l&uacute;c n&agrave;o cũng thắng đậm ph&ograve;ng v&eacute;. Dẫu vậy, diễn xuất của anh chưa bao giờ g&acirc;y thất vọng. Đầu năm, Th&aacute;i H&ograve;a lấy nước mắt bằng anh Bảy Theo cương trực (<a href=\"https://www.galaxycine.vn/phim/dia-dao-mat-troi-trong-bong-toi/\">Địa Đạo: Mặt Trời Trong B&oacute;ng Tối</a>). Cuối năm, Th&aacute;i H&ograve;a khiến kh&aacute;n giả rợn t&oacute;c g&aacute;y với g&atilde; kh&ocirc;ng tặc vừa &ldquo;lịch sự&rdquo; vừa &ldquo;th&acirc;n thiện&rdquo;. Nếu kh&ocirc;ng lộ diện sẵn từ poster, ở cảnh đầu ti&ecirc;n Th&aacute;i H&ograve;a xuất hiện, sẽ kha kh&aacute; người xem nghĩ anh chỉ l&agrave; nạn nh&acirc;n tr&ecirc;n chuyến bay b&atilde;o tố. Bởi lẽ, Long l&uacute;c ấy thật sự rất b&igrave;nh thường! Thế nhưng, vừa qua cổng an ninh, &aacute;nh mắt Long biến h&oacute;a ngay lập tức! Đ&ocirc;i mắt lạnh l&ugrave;ng, c&aacute;ch nhấn nh&aacute; lời thoại đủ l&agrave;m ai yếu tim phải &ocirc;m ngực của Th&aacute;i H&ograve;a chắc chắn sẽ &aacute;m ảnh c&ocirc;ng ch&uacute;ng tận sau khi ra về. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img alt=\"\" height=\"314\" src=\"/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-11_1758600132464.jpg\" width=\"600\" /></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Thời điểm <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> ra mắt poster đầu ti&ecirc;n, Kaity Nguyễn g&acirc;y ấn tượng lập tức nhờ diễn xuất bằng mắt qu&aacute; đỗi xuất thần. V&agrave;o phim, từng ph&acirc;n cảnh c&ocirc; xuất hiện cũng đều giữ nguy&ecirc;n phong độ. Trinh kh&oacute;c, cười, phẫn nộ&hellip; lu&ocirc;n khiến tất cả bị cuốn theo. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\"><img alt=\"\" height=\"360\" src=\"/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-4_1758600178903.jpg\" width=\"600\" /></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Chưa quen mặt bằng Kaity Nguyễn, Tr&acirc;m Anh vai nữ tiếp vi&ecirc;n trưởng Nh&agrave;n l&agrave; một bất ngờ lớn. Đặc biệt, khi đối diễn c&ugrave;ng Th&aacute;i H&ograve;a, diễn xuất của Tr&acirc;m Anh đủ để nhận cơn mưa lời khen. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\"><img alt=\"\" height=\"313\" src=\"/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-8_1758600151370.jpg\" width=\"600\" /></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Thanh Sơn l&agrave; ng&ocirc;i sao quen thuộc tr&ecirc;n phim truyền h&igrave;nh khu vực ph&iacute;a Bắc nhưng với m&agrave;n ảnh rộng, anh đ&atilde; &ldquo;nghỉ ngơi&rdquo; qu&aacute; l&acirc;u từ <i>M&ugrave;i Cỏ Ch&aacute;y</i>. Xuất hiện &iacute;t ỏi ở <i>Y&ecirc;u Nhầm Bạn Th&acirc;n</i>, t&ecirc;n tuổi anh chỉ thật sự b&ugrave;ng nổ nhờ <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a>. B&igrave;nh mạnh mẽ, rắn rỏi v&agrave; điềm tĩnh, l&agrave; niềm hi vọng cho cả chuyến bay. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\"><img alt=\"\" height=\"338\" src=\"/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-6_1758600198551.jpg\" width=\"600\" /></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Đa số cảnh h&agrave;nh động trong phim do diễn vi&ecirc;n tự thể hiện chứ kh&ocirc;ng cần đ&oacute;ng thế. Ngo&agrave;i sự hi sinh lăn xả của d&agrave;n cast, đạo diễn, quay phim v&agrave; bi&ecirc;n tập cũng xuất sắc kh&oacute; thể ch&ecirc; v&agrave;o đ&acirc;u được. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\"><img alt=\"\" height=\"470\" src=\"/media/2025/9/23/tu-chien-tren-khong-phim-viet-xuat-sac-top-dau-2025-2_1758600213016.jpg\" width=\"600\" /></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\"><a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> c&oacute; nhiều cảnh quay cận mặt &ndash; điểm yếu ch&iacute; mạng nếu diễn vi&ecirc;n diễn xuất kh&ocirc;ng tốt. Thế nhưng, nhờ d&agrave;n diễn vi&ecirc;n hết sức tr&ograve;n vai Th&aacute;i Ho&agrave;, Kaity Nguyễn, Thanh Sơn, Xu&acirc;n Ph&uacute;c, V&otilde; Điền Gia Huy, Trần Ngọc V&agrave;ng, Ma Ran Đ&ocirc;, Lợi Trần, Tr&acirc;m Anh, Xu&acirc;n Văn, Bảo Định, Ray Nguyễn&hellip; Kh&aacute;n giả được thưởng thức một đại tiệc diễn xuất!</span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">Th&agrave;nh c&ocirc;ng của <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> gi&uacute;p nhiều gương mặt tỏa s&aacute;ng. Đ&oacute; l&agrave; Bảo Định - đối diễn xuất sắc với &ldquo;người cha&rdquo; Th&aacute;i H&ograve;a. V&otilde; Điền Gia Huy lột x&aacute;c ho&agrave;n to&agrave;n so với vẻ hiền l&agrave;nh ở <a href=\"https://www.galaxycine.vn/phim/thua-me-con-di/\"><i>Thưa Mẹ Con Đi</i></a>. Sỹ To&agrave;n, Ray Nguyễn, Lợi Trần, Xu&acirc;n Văn, Ma Ran Đ&ocirc;, Trần Ngọc V&agrave;ng, Xu&acirc;n Ph&uacute;c, Tiểu Bảo Quốc v&agrave; Thi&ecirc;n T&uacute; đều c&oacute; khoảnh khoắc đ&aacute;ng nhớ. </span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:115%\">C&oacute; thể n&oacute;i, <a href=\"https://www.galaxycine.vn/dat-ve/tu-chien-tren-khong/\"><b>Tử Chiến Tr&ecirc;n Kh&ocirc;ng</b></a> l&agrave; một trong những phim Việt Nam xuất sắc nhất từ trước đến nay. Hi vọng, sự ủng hộ của c&ocirc;ng ch&uacute;ng sẽ gi&uacute;p c&aacute;c nh&agrave; l&agrave;m phim nước ta th&ecirc;m phần quyết t&acirc;m để mang th&ecirc;m nhiều đề t&agrave;i kh&oacute; l&ecirc;n m&agrave;n ảnh rộng. </span></span></span></p>\n\n<p></p>\n',
             1,  -- isHot = true theo yêu cầu is_hot = 1
             1,
             NOW());
INSERT INTO film_comments (
    id,
    name,
    slug,
    views,
    type,
    short_description,
    image_landscape,
    image_portrait,
    description,
    is_hot,
    display_order,
    created_at
) VALUES (
             '1cbf47ae-9b43-45e3-9f53-4a495a956a7a',
             '[Review] The Conjuring Last Rites: Chương Cuối Trọn Vẹn Cảm Xúc',
             'review-the-conjuring-last-rites-chuong-cuoi-tron-ven-cam-xuc',
             399,
             'review',
             '<p><span style=\"font-size:14px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b><i><span style=\"line-height:115%\">The Conjuring: Last Rites</span></i></b><span style=\"line-height:115%\">, đ&aacute;nh dấu sự kết th&uacute;c cho franchise <i>&Aacute;m Ảnh Kinh Ho&agrave;ng</i> suốt h&agrave;nh tr&igrave;nh hơn 10 năm.</span></span></span></p>\n',
             'https://cdn.galaxycine.vn/media/2025/9/16/750-the-conjuring_1758016483478.jpg',
             'https://cdn.galaxycine.vn/media/2025/9/16/500-chuan_1758016572394.jpg',
